selector_to_html = {"a[href=\"#losses\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Losses<a class=\"headerlink\" href=\"#losses\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">diffuser.solve(inlet_state=...,</span> <span class=\"pre\">mass_flow=...,</span> <span class=\"pre\">transport=...)</span></code> charges\nG\u00fclich\u2019s Table 3.8 (2), each term referred to <code class=\"docutils literal notranslate\"><span class=\"pre\">u2\u00b2/2</span></code>:</p>", "a[href=\"#does-it-pay\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Does it pay?<a class=\"headerlink\" href=\"#does-it-pay\" title=\"Link to this heading\">\u00b6</a></h2><p>Not always. The channels recover only the optimum <code class=\"docutils literal notranslate\"><span class=\"pre\">cp</span></code> for their length,\ntypically 0.55 to 0.65, of a throat head that is still most of the impeller\u2019s\ndynamic head. A vaneless volute behind a small, fast impeller can lose less.\nIn the dual-expander project, G\u00fclich\u2019s diffuser and an Aungier volute behind it\nlose about twice what the vaneless volute alone does. A vaned diffuser still\nevens out the radial thrust, which a single volute does not. Compare the two\nwith the same loss models before choosing.</p>", "a[href=\"../autoapi/pyskyfire/pump/impeller/Impeller.html#pyskyfire.pump.impeller.Impeller\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.Impeller\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Impeller</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Q</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">H</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">shaft_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_hub_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_count</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_thickness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hydraulic_efficiency</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">beta2_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">psi</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d2</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">u2</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fT</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">b2</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">phi1</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d1</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">beta1_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">incidence_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_prewhirl</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wrap_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">volumetric_efficiency</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">tip_clearance</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">meridional</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">axial_length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_settings</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">splitter</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">COUNTERCLOCKWISE</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Size a radial impeller; call build_geometry() to generate pyTurbo surfaces.</p><p>Required lengths are in metres. <code class=\"docutils literal notranslate\"><span class=\"pre\">blade_thickness</span></code> is total section-normal\nbody thickness: a float or function of chord_fraction, span_fraction, x, r.\nAngle and prewhirl functions accept span_fraction, x, r. Span runs hub to\nblade tip, including when tip clearance is present. <code class=\"docutils literal notranslate\"><span class=\"pre\">phi1</span></code> refers to the\nunblocked inlet annulus, and d1 overrides its sizing equation.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">H</span></code> is the total head at the impeller outlet and <code class=\"docutils literal notranslate\"><span class=\"pre\">hydraulic_efficiency</span></code>\nthe impeller\u2019s own (see the module notes); it is a supplied assumption,\nnever predicted here. The design is closed on one quantity. By default\n<code class=\"docutils literal notranslate\"><span class=\"pre\">beta2_deg</span></code> is solved and the outlet diameter comes from one of <code class=\"docutils literal notranslate\"><span class=\"pre\">psi</span></code>,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">d2</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">u2</span></code> or a supplied <code class=\"docutils literal notranslate\"><span class=\"pre\">meridional</span></code>, or failing all of them from\nEq. (3.26) at <code class=\"docutils literal notranslate\"><span class=\"pre\">fT</span></code>. Give <code class=\"docutils literal notranslate\"><span class=\"pre\">beta2_deg</span></code> instead and <code class=\"docutils literal notranslate\"><span class=\"pre\">d2</span></code> is solved. Giving\nboth over-specifies the wheel. The solved angle is the one below the peak\nof the swirl it can deliver: at low specific speed that peak is broad and\nflat, and a head above it cannot be had at any angle, which is reported\nwith the head coefficient that can.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">blade_count</span></code> is always an input. G\u00fclich rejects empirical blade-count\nformulas as likely to violate the criteria that actually set it: pressure\npulsations against the collector, blade loading, head-curve stability.\nSplitters do not count toward it in the slip prediction.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">incidence_deg</span></code> means metal angle minus unblocked relative inlet flow\nangle. No leakage is assumed for volumetric_efficiency=1. <code class=\"docutils literal notranslate\"><span class=\"pre\">b2</span></code> defaults\nto Eq. (7.1).</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">rotation</span></code> is which way the wheel turns about its own +x shaft, and only\nmirrors the blades: every velocity triangle is a magnitude in the rotating\nframe and is the same either way. It has to match the sense of the volute\ncollecting the discharge, once both are placed.\nCreate a new Impeller to change design inputs; build_geometry can be repeated\nat different numerical resolutions using the same resolved definition.</p></dd>", "a[href=\"../autoapi/pyskyfire/pump/diffuser/VanedDiffuser.html#pyskyfire.pump.diffuser.VanedDiffuser.from_impeller\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.diffuser.VanedDiffuser.from_impeller\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_impeller</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">impeller</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"o\"><span class=\"pre\">**</span></span><span class=\"n\"><span class=\"pre\">design</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Design the diffuser for an <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Impeller</span></code>\u2019s outlet.</p><p>The swirl is the impeller\u2019s slip prediction on its mean streamline, and\nthe head its outlet head. <code class=\"docutils literal notranslate\"><span class=\"pre\">rho</span></code> defaults to the impeller\u2019s.</p></dd>", "a[href=\"#the-vanes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">The vanes<a class=\"headerlink\" href=\"#the-vanes\" title=\"Link to this heading\">\u00b6</a></h2><p>The vanes are thin: <code class=\"docutils literal notranslate\"><span class=\"pre\">vane_thickness_ratio</span></code> of <code class=\"docutils literal notranslate\"><span class=\"pre\">d2</span></code>, 0.012 by default, within\nG\u00fclich\u2019s 0.01 to 0.015 (7.9.2). They are held at that thickness and rounded to\na point at both ends. Each vane is a camber line in two parts:</p>", "a[href=\"#checking-a-design\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Checking a design<a class=\"headerlink\" href=\"#checking-a-design\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">diffuser.checks</span></code> holds G\u00fclich\u2019s criteria for a finished diffuser (7.9.1 item\n10). They are reported, never enforced; only a geometry that cannot be drawn\nraises.</p>", "a[href=\"#how-it-is-sized\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">How it is sized<a class=\"headerlink\" href=\"#how-it-is-sized\" title=\"Link to this heading\">\u00b6</a></h2><p>The design follows G\u00fclich, <em>Centrifugal Pumps</em>, chapter 7.9:</p>", "a[href=\"#design-a-vaned-diffuser\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Design a vaned diffuser<a class=\"headerlink\" href=\"#design-a-vaned-diffuser\" title=\"Link to this heading\">\u00b6</a></h1><p>A vaned diffuser sits between an impeller and its volute. Its vanes take the\nswirl out of the impeller discharge and turn the flow outward through widening\nchannels, so the volute behind it collects slow, low-swirl flow instead of flow\nat the impeller\u2019s own speed.</p><p>Design one from the impeller it follows:</p>", "a[href=\"../autoapi/pyskyfire/pump/index.html#module-pyskyfire.pump\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.pump<a class=\"headerlink\" href=\"#module-pyskyfire.pump\" title=\"Link to this heading\">\u00b6</a></h1><p>Preliminary centrifugal pump design with optional pyTurbo blade generation.</p>", "a[href=\"../autoapi/pyskyfire/pump/diffuser/VanedDiffuser.html#pyskyfire.pump.diffuser.VanedDiffuser\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.diffuser.VanedDiffuser\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.diffuser.</span></span><span class=\"sig-name descname\"><span class=\"pre\">VanedDiffuser</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">flow</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">b2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">u2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">c2u</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">impeller_blade_count</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">H</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nq</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">vane_count</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">gap_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_width_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.15</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">outer_diameter_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">outlet_width_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">throat_factor</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">deceleration</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">vane_thickness_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.012</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">COUNTERCLOCKWISE</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A vaned radial diffuser designed from the impeller it follows.</p><p>Build one with <a class=\"reference internal\" href=\"#pyskyfire.pump.diffuser.VanedDiffuser.from_impeller\" title=\"pyskyfire.pump.diffuser.VanedDiffuser.from_impeller\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">from_impeller()</span></code></a>. The direct constructor takes the\nimpeller outlet as numbers: <code class=\"docutils literal notranslate\"><span class=\"pre\">flow</span></code> through the impeller [m\u00b3/s], its\noutlet diameter <code class=\"docutils literal notranslate\"><span class=\"pre\">d2</span></code> and width <code class=\"docutils literal notranslate\"><span class=\"pre\">b2</span></code> [m], tip speed <code class=\"docutils literal notranslate\"><span class=\"pre\">u2</span></code> and outlet\nswirl <code class=\"docutils literal notranslate\"><span class=\"pre\">c2u</span></code> [m/s], blade count, speed <code class=\"docutils literal notranslate\"><span class=\"pre\">n</span></code> [rpm], head <code class=\"docutils literal notranslate\"><span class=\"pre\">H</span></code> [m] (the\nhead at the impeller outlet, used for the gap and exit-energy rules),\nspecific speed <code class=\"docutils literal notranslate\"><span class=\"pre\">nq</span></code>, density <code class=\"docutils literal notranslate\"><span class=\"pre\">rho</span></code> [kg/m\u00b3] and <code class=\"docutils literal notranslate\"><span class=\"pre\">rotation</span></code>.</p><p>Design inputs, with G\u00fclich\u2019s ranges:</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
